INSERT INTO public.content_items
(id,section,title,slug,description,price,currency,brand,model,location,features,image_urls,availability,published,sort_order,contact_label,contact_url,affiliate_url)
SELECT x.id::uuid,x.section,x.title,x.slug,
CASE WHEN x.section='supercar_rentals' THEN 'Modelo de referencia. El importe es orientativo, no una tarifa de AUREON ni confirmación de flota. Confirma disponibilidad, seguro, fianza y condiciones con el proveedor.'
WHEN x.section='luxury_cars' THEN 'Ficha procedente del catálogo facilitado. Confirma estado, titularidad y disponibilidad antes de cualquier operación.'
WHEN x.slug='villa-la-moraleja' THEN 'Residencia contemporánea en La Moraleja con jardín, piscina y terrazas. Comercialización bajo consulta privada; documentación y condiciones por confirmar.'
WHEN x.slug='villa-estremera-madrid' THEN 'Propiedad en Estremera para consultar celebraciones, eventos privados y estancias. Capacidad, precio y disponibilidad se confirman con el responsable.'
WHEN x.slug='dolores-inversion-alicante' THEN 'Estudio de 36 m² para reformar en Dolores, Alicante. Precio anunciado sin reformar: 60.000 €. Rentabilidad, reforma y valor posterior no garantizados; verificar documentación, cargas y costes antes de invertir.'
ELSE '' END,
x.price,'EUR',x.brand,x.model,x.location,x.features,
ARRAY(SELECT jsonb_array_elements_text(x.image_urls)),'available',true,0,'Consultar disponibilidad',NULL,NULL
FROM rows x
ON CONFLICT (slug) DO UPDATE SET
 section=excluded.section,title=excluded.title,description=excluded.description,price=excluded.price,
 brand=excluded.brand,model=excluded.model,location=excluded.location,features=excluded.features,
 image_urls=excluded.image_urls,availability=excluded.availability,published=excluded.published,updated_at=now();
